"""Lint SKILL.md files that use the Skill tool for invocation wording."""

from __future__ import annotations

import argparse
import re
import sys
from pathlib import Path

PATTERN_A_PHRASE = "Invoke the Skill tool"
PATTERN_B_PHRASE = "via the Skill tool"
INVOCATION_LINE_REGEX = re.compile(
    r"\b(?:re-)?[Ii]nvoke\b\s+(?:the\s+)?(?:\*\*[^*\n]{1,40}\*\*\s+)?`/[\w-]+`(?:\s+skill\b)?"
)
CODE_FENCE_REGEX = re.compile(r"^\s*```")
GLOB_PATTERNS = ("skills/*/SKILL.md", ".claude/skills/*/SKILL.md")
MIN_QUOTED_LENGTH = 2


class LintError(Exception):
    """Raised for internal read errors."""


def extract_frontmatter_and_body(text: str) -> tuple[str | None, str, int]:
    text = text.lstrip("\ufeff").replace("\r\n", "\n")
    if not text.startswith("---\n"):
        return None, text, 1
    remainder = text[len("---\n") :]
    end_marker = "\n---\n"
    idx = remainder.find(end_marker)
    if idx < 0:
        if remainder.endswith("\n---"):
            return remainder[: -len("\n---")], "", 0
        return None, text, 1
    frontmatter = remainder[:idx]
    body = remainder[idx + len(end_marker) :]
    frontmatter_lines = frontmatter.count("\n") + 1
    body_start_line = 2 + frontmatter_lines + 1
    return frontmatter, body, body_start_line


def _strip_quotes(value: str) -> str:
    value = value.strip()
    if len(value) >= MIN_QUOTED_LENGTH and value[0] == value[-1] and value[0] in {"'", '"'}:
        return value[1:-1]
    return value


def _strip_inline_comment(value: str) -> str:
    in_single = False
    in_double = False
    for index, char in enumerate(value):
        if char == "'" and not in_double:
            in_single = not in_single
        elif char == '"' and not in_single:
            in_double = not in_double
        elif (
            char == "#"
            and not in_single
            and not in_double
            and (index == 0 or value[index - 1].isspace())
        ):
            return value[:index].rstrip()
    return value.strip()


def _quotes_balanced(value: str) -> bool:
    in_single = False
    in_double = False
    for char in value:
        if char == "'" and not in_double:
            in_single = not in_single
        elif char == '"' and not in_single:
            in_double = not in_double
    return not in_single and not in_double


def _split_flow_list_inner(inner: str) -> list[str] | None:
    items: list[str] = []
    current: list[str] = []
    in_single = False
    in_double = False
    for char in inner:
        if char == "'" and not in_double:
            in_single = not in_single
            current.append(char)
        elif char == '"' and not in_single:
            in_double = not in_double
            current.append(char)
        elif char == "," and not in_single and not in_double:
            item = _strip_quotes("".join(current).strip())
            if item:
                items.append(item)
            current = []
        else:
            current.append(char)
    if in_single or in_double:
        return None
    item = _strip_quotes("".join(current).strip())
    if item:
        items.append(item)
    return items


def _parse_allowed_tools_tokens(value: str) -> list[str] | None:
    value = _strip_inline_comment(value.strip())
    if not value:
        return []
    if not _quotes_balanced(value):
        return None
    if value.startswith("["):
        if not value.endswith("]"):
            return None
        return _split_flow_list_inner(value[1:-1])
    stripped = _strip_quotes(value)
    return [part.strip() for part in stripped.split(",") if part.strip()]


def allowed_tools_contains_skill(frontmatter_text: str) -> bool:
    try:
        lines = frontmatter_text.replace("\r\n", "\n").split("\n")
        if any(line.lstrip().startswith("-") for line in lines if line.strip()):
            # A top-level YAML sequence is not a mapping. Indented block-list
            # entries under allowed-tools are handled after the key is found.
            first = next(line for line in lines if line.strip())
            if first.lstrip().startswith("-"):
                return False
        for idx, line in enumerate(lines):
            match = re.match(r"^allowed-tools\s*:\s*(.*)$", line)
            if not match:
                continue
            value = match.group(1)
            if value.strip():
                inline_tokens = _parse_allowed_tools_tokens(value)
                return False if inline_tokens is None else "Skill" in inline_tokens
            tokens: list[str] = []
            for child in lines[idx + 1 :]:
                if not child.startswith((" ", "\t")):
                    break
                stripped = child.strip()
                if not stripped or stripped.startswith("#"):
                    continue
                item = re.match(r"^-\s*(.+)$", stripped)
                if not item:
                    return False
                parsed = _parse_allowed_tools_tokens(item.group(1))
                if parsed is None:
                    return False
                tokens.extend(parsed)
            return "Skill" in tokens
    except Exception:
        return False
    return False


def body_has_invocation_phrase(body: str) -> bool:
    return PATTERN_A_PHRASE in body or PATTERN_B_PHRASE in body


def body_per_invocation_violations(body: str, body_start_line: int) -> list[tuple[int, str]]:
    violations: list[tuple[int, str]] = []
    in_fence = False
    for body_line_idx, line in enumerate(body.split("\n")):
        if CODE_FENCE_REGEX.match(line):
            in_fence = not in_fence
            continue
        if in_fence:
            continue
        if INVOCATION_LINE_REGEX.search(line) and PATTERN_B_PHRASE not in line:
            violations.append((body_start_line + body_line_idx, line))
    return violations


def find_skill_files(root: Path) -> list[Path]:
    files: list[Path] = []
    for pattern in GLOB_PATTERNS:
        files.extend(sorted(root.glob(pattern)))
    return files


def _rel(path: Path, root: Path) -> str:
    try:
        return str(path.relative_to(root))
    except ValueError:
        return str(path)


def lint_file(path: Path, root: Path) -> list[str]:
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        raise LintError(f"lint-skill-invocations: {path}: cannot read file: {exc}") from exc
    frontmatter, body, body_start_line = extract_frontmatter_and_body(text)
    if frontmatter is None or not allowed_tools_contains_skill(frontmatter):
        return []
    rel = _rel(path, root)
    messages: list[str] = []
    if not body_has_invocation_phrase(body):
        messages.append(
            f"lint-skill-invocations: {rel}: declares 'Skill' in allowed-tools but contains no "
            f"'{PATTERN_A_PHRASE}' or '{PATTERN_B_PHRASE}' invocation step"
        )
    for absolute_line, _line_text in body_per_invocation_violations(body, body_start_line):
        messages.append(
            f"lint-skill-invocations: {rel}:{absolute_line}: 'Invoke `/<cmd>`' without "
            f"'{PATTERN_B_PHRASE}' on the same line — see skills/shared/subskill-invocation.md"
        )
    return messages


def _parse_args(argv: list[str]) -> argparse.Namespace | None:
    parser = argparse.ArgumentParser(prog="cli.py lint skill-invocations", description=__doc__)
    _ = parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parents[1])
    try:
        return parser.parse_args(argv)
    except SystemExit as exc:
        if exc.code == 0:
            raise
        return None

from __future__ import annotations

from pathlib import Path

import pytest

from lint_skill_invocations import main


def write_skill(root: Path, rel: str, body: str) -> None:
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    _ = path.write_text(body, encoding="utf-8")


def run(root: Path, capsys: pytest.CaptureFixture[str]) -> tuple[int, str]:
    rc = main(["--root", str(root)])
    return rc, capsys.readouterr().err


def skill_doc(allowed_tools: str, body: str) -> str:
    return f"---\nname: fixture\ndescription: fixture\nallowed-tools: {allowed_tools}\n---\n\n{body}\n"


@pytest.mark.parametrize(
    ("label", "allowed", "body"),
    [
        ("pattern-a", "Bash, Skill", "Invoke the Skill tool:\n- skill: foo"),
        ("pattern-b", "Bash, Read, Skill", "Invoke `/foo` via the Skill tool."),
        ("no-skill", "Bash, Read", "No invocation phrase."),
        ("flow-list", "[Bash, Read, Skill]", "Invoke `/thing` via the Skill tool."),
        ("quoted-flow-list", '["Bash", "Skill"]', "Invoke `/thing` via the Skill tool."),
        ("single-quoted-flow-list", "['Bash', 'Skill']", "Invoke `/thing` via the Skill tool."),
        ("substring", "Bash, SkillCheck", "No invocation phrase."),
        ("quoted", '"Bash, Skill"', "Invoke the Skill tool:\n- skill: foo"),
    ],
)
def test_allowed_tools_shapes_pass(tmp_path: Path, capsys: pytest.CaptureFixture[str], label: str, allowed: str, body: str) -> None:
    write_skill(tmp_path, f"skills/{label}/SKILL.md", skill_doc(allowed, body))
    rc, err = run(tmp_path, capsys)
    assert rc == 0, err


def test_block_sequence_allowed_tools(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(
        tmp_path,
        "skills/block/SKILL.md",
        "---\nname: block\ndescription: block\nallowed-tools:\n  - Bash\n  - Skill\n---\n\nInvoke `/x` via the Skill tool.\n",
    )
    rc, err = run(tmp_path, capsys)
    assert rc == 0, err


def test_malformed_allowed_tools_gate_false(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(
        tmp_path,
        "skills/malformed-bracket/SKILL.md",
        skill_doc("[Bash, Skill", "Missing phrase but malformed frontmatter."),
    )
    write_skill(
        tmp_path,
        "skills/malformed-quote/SKILL.md",
        skill_doc('"Bash, Skill', "Missing phrase but unclosed quote."),
    )
    rc, err = run(tmp_path, capsys)
    assert rc == 0, err


def test_file_level_violation(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(tmp_path, "skills/missing/SKILL.md", skill_doc("Bash, Skill", "Missing phrase."))
    rc, err = run(tmp_path, capsys)
    assert rc == 1
    assert "skills/missing/SKILL.md" in err
    assert "declares 'Skill' in allowed-tools" in err


def test_two_violations_and_claude_tree(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(tmp_path, "skills/one/SKILL.md", skill_doc("Skill", "Missing."))
    write_skill(tmp_path, ".claude/skills/two/SKILL.md", skill_doc("Skill", "Missing too."))
    rc, err = run(tmp_path, capsys)
    assert rc == 1
    assert "skills/one/SKILL.md" in err
    assert ".claude/skills/two/SKILL.md" in err


def test_crlf_and_bom(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    path = tmp_path / "skills/crlf/SKILL.md"
    path.parent.mkdir(parents=True)
    _ = path.write_bytes(
        b"\xef\xbb\xbf---\r\nname: crlf\r\ndescription: crlf\r\nallowed-tools: Bash, Skill\r\n---\r\n\r\nInvoke `/foo` via the Skill tool.\r\n"
    )
    rc, err = run(tmp_path, capsys)
    assert rc == 0, err


def test_non_utf8_exit_2_wins_over_violation(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    bad = tmp_path / "skills/bad/SKILL.md"
    bad.parent.mkdir(parents=True)
    _ = bad.write_bytes(b"\xff\xfe")
    write_skill(tmp_path, "skills/vio/SKILL.md", skill_doc("Skill", "Missing."))
    rc, err = run(tmp_path, capsys)
    assert rc == 2
    assert "bad/SKILL.md" in err
    assert "cannot read file" in err
    assert "vio/SKILL.md" in err


def test_per_invocation_line_violations(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(
        tmp_path,
        "skills/lines/SKILL.md",
        skill_doc(
            "Skill",
            "To pass total omission: Invoke `/setup` via the Skill tool.\n\nBut these are bare:\n- Invoke `/foo` first.\n- Then invoke `/bar` next.",
        ),
    )
    rc, err = run(tmp_path, capsys)
    assert rc == 1
    assert "skills/lines/SKILL.md:10:" in err
    assert "skills/lines/SKILL.md:11:" in err


def test_code_fence_and_citation_exemptions(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(
        tmp_path,
        "skills/exempt/SKILL.md",
        skill_doc(
            "Skill",
            "Invoke `/setup` via the Skill tool.\n\n```\nInvoke `/foo` bare.\n```\n\nAlways invoke the helper script before calling `/release`.\nInvoke the **Rebase + Re-bump Sub-procedure** which internally re-runs `/release`.",
        ),
    )
    rc, err = run(tmp_path, capsys)
    assert rc == 0, err


def test_bare_reinvoke_is_violation(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None:
    write_skill(
        tmp_path,
        "skills/reinvoke/SKILL.md",
        skill_doc("Skill", "Invoke `/setup` via the Skill tool.\n\nThen re-invoke `/issue` if needed."),
    )
    rc, err = run(tmp_path, capsys)
    assert rc == 1
    assert "skills/reinvoke/SKILL.md" in err
    assert "via the Skill tool" in err
